/* ── Interactive Guided Tour & Mascot Styles ── */
.wb-tour-addon-widget {
  display: block;
  font-family: var(--font-sans, system-ui, -apple-system, sans-serif);
}

/* Floating Launcher Button */
.wb-tour-launcher-btn {
  position: fixed;
  z-index: 99990;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px 8px 10px;
  background: rgba(15, 23, 42, 0.88);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(99, 102, 241, 0.3);
  border-radius: 9999px;
  color: #f8fafc;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s, background 0.2s;
  user-select: none;
}
.wb-tour-launcher-btn:hover {
  transform: translateY(-2px) scale(1.02);
  background: rgba(19, 27, 46, 0.98);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45), 0 0 16px var(--tour-accent, #6366f1);
  border-color: var(--tour-accent, #6366f1);
}
.wb-tour-launcher-btn:active {
  transform: translateY(0) scale(0.98);
}

.wb-tour-launcher-bottom-right { bottom: 24px; right: 24px; }
.wb-tour-launcher-bottom-left  { bottom: 24px; left: 24px; }
.wb-tour-launcher-top-right   { top: 24px; right: 24px; }
.wb-tour-launcher-top-left    { top: 24px; left: 24px; }

.wb-tour-launcher-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.1);
  border: 1.5px solid var(--tour-accent, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.wb-tour-launcher-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.wb-tour-launcher-icon {
  font-size: 1.15rem;
  line-height: 1;
}
.wb-tour-launcher-text {
  letter-spacing: -0.01em;
  white-space: nowrap;
}
.wb-tour-launcher-pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--tour-accent, #6366f1);
  box-shadow: 0 0 8px var(--tour-accent, #6366f1);
  animation: wbTourPulse 1.8s infinite;
}
@keyframes wbTourPulse {
  0% { transform: scale(0.9); opacity: 0.8; }
  50% { transform: scale(1.4); opacity: 1; box-shadow: 0 0 12px var(--tour-accent, #6366f1); }
  100% { transform: scale(0.9); opacity: 0.8; }
}

/* ── Fullscreen Overlay & Spotlight ── */
#wb-tour-overlay {
  position: fixed;
  inset: 0;
  z-index: 999990;
  pointer-events: auto;
  font-family: var(--font-sans, system-ui, -apple-system, sans-serif);
  animation: wbTourFadeIn 0.25s ease-out;
}
@keyframes wbTourFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.wb-tour-spotlight-hole {
  position: fixed;
  border-radius: 12px;
  pointer-events: none;
  transition: top 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              left 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              width 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              height 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 0 0 9999px rgba(10, 16, 32, var(--tour-opacity, 0.78)),
              0 0 24px rgba(99, 102, 241, 0.55);
  border: 2px solid var(--tour-accent, #6366f1);
  outline: 2px dashed rgba(255, 255, 255, 0.35);
  box-sizing: border-box;
}

/* ── Tour Popover Card ── */
.wb-tour-card {
  position: fixed;
  z-index: 999995;
  width: 360px;
  max-width: calc(100vw - 32px);
  border-radius: 18px;
  box-sizing: border-box;
  padding: 20px 22px;
  transition: top 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              left 0.35s cubic-bezier(0.16, 1, 0.3, 1),
              opacity 0.2s, transform 0.2s;
  box-shadow: 0 24px 50px rgba(0, 0, 0, 0.6), 0 0 1px rgba(255, 255, 255, 0.2);
}

/* Themes */
.wb-tour-theme-glass {
  background: rgba(19, 27, 46, 0.92);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #f8fafc;
}
.wb-tour-theme-dark {
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #f8fafc;
}
.wb-tour-theme-light {
  background: #ffffff;
  border: 1px solid rgba(0, 0, 0, 0.1);
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.15);
  color: #0f172a;
}

/* Mascot Avatar Styling */
.wb-tour-avatar-peeking {
  position: absolute;
  top: -34px;
  left: 20px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: #0f172a;
  border: 2.5px solid var(--tour-accent, #6366f1);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  animation: wbTourBob 2.8s ease-in-out infinite;
}
.wb-tour-avatar-peeking img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
@keyframes wbTourBob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.wb-tour-avatar-companion {
  position: absolute;
  top: -28px;
  right: 20px;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: #0f172a;
  border: 2px solid var(--tour-accent, #6366f1);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  animation: wbTourBob 2.8s ease-in-out infinite;
}
.wb-tour-avatar-companion img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.wb-tour-avatar-badge {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  overflow: hidden;
  border: 1.5px solid var(--tour-accent, #6366f1);
  display: inline-block;
  vertical-align: middle;
  margin-right: 6px;
}
.wb-tour-avatar-badge img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Card Header */
.wb-tour-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.wb-tour-badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 20px;
  font-size: 0.68rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: rgba(99, 102, 241, 0.18);
  color: #c7d2fe;
  border: 1px solid rgba(99, 102, 241, 0.35);
}
.wb-tour-step-counter {
  font-size: 0.72rem;
  font-weight: 700;
  color: #94a3b8;
}
.wb-tour-close-btn {
  background: none;
  border: none;
  color: #94a3b8;
  cursor: pointer;
  font-size: 1.1rem;
  padding: 2px 6px;
  border-radius: 6px;
  line-height: 1;
  transition: color 0.15s, background 0.15s;
}
.wb-tour-close-btn:hover {
  color: #f87171;
  background: rgba(239, 68, 68, 0.1);
}

/* Card Content */
.wb-tour-card-title {
  font-size: 1.05rem;
  font-weight: 800;
  margin: 0 0 8px 0;
  line-height: 1.3;
  letter-spacing: -0.02em;
}
.wb-tour-card-desc {
  font-size: 0.84rem;
  line-height: 1.55;
  color: #cbd5e1;
  margin: 0 0 16px 0;
}
.wb-tour-theme-light .wb-tour-card-desc {
  color: #475569;
}

/* Progress Dots */
.wb-tour-progress-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 16px;
}
.wb-tour-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transition: all 0.25s ease;
}
.wb-tour-theme-light .wb-tour-dot {
  background: rgba(0, 0, 0, 0.15);
}
.wb-tour-dot.active {
  width: 22px;
  border-radius: 4px;
  background: var(--tour-accent, #6366f1);
  box-shadow: 0 0 8px var(--tour-accent, #6366f1);
}

/* Card Actions */
.wb-tour-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.wb-tour-theme-light .wb-tour-card-actions {
  border-top: 1px solid rgba(0, 0, 0, 0.08);
}
.wb-tour-skip-btn {
  background: none;
  border: none;
  color: #94a3b8;
  font-size: 0.76rem;
  font-weight: 600;
  cursor: pointer;
  padding: 6px 10px;
  border-radius: 6px;
  transition: color 0.15s;
}
.wb-tour-skip-btn:hover {
  color: #ffffff;
}
.wb-tour-nav-btns {
  display: flex;
  align-items: center;
  gap: 6px;
}
.wb-tour-btn {
  padding: 7px 14px;
  border-radius: 8px;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
}
.wb-tour-btn-back {
  background: rgba(255, 255, 255, 0.08);
  color: #cbd5e1;
  border: 1px solid rgba(255, 255, 255, 0.12);
}
.wb-tour-theme-light .wb-tour-btn-back {
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}
.wb-tour-btn-back:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
}
.wb-tour-btn-back:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
.wb-tour-btn-next {
  background: var(--tour-accent, #6366f1);
  color: #ffffff;
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.4);
}
.wb-tour-btn-next:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
}
.wb-tour-btn-next:active {
  transform: translateY(0);
}

