function onMount(el, props) {
  var root = el.querySelector('.wb-tour-addon-widget');
  if (!root) return;

  var esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  };

  var steps = Array.isArray(props.steps) ? props.steps : [];
  if (steps.length === 0) {
    // Built-in default steps fallback
    steps = [
      { targetSelector: 'header, nav, .widget-type-navbar', title: 'Welcome! 👋', content: 'Explore our top navigation to discover sections and services.', placement: 'bottom' },
      { targetSelector: '.wb-registration-widget, form, .widget-type-registration_form', title: 'Quick Registration 📝', content: 'Complete this form to reserve your slot instantly.', placement: 'top' },
      { targetSelector: 'footer, .widget-type-footer', title: 'Contact & Support 📍', content: 'Find official contact details, addresses, and social links here.', placement: 'top' }
    ];
  }

  var currentStep = 0;
  var overlayEl = null;
  var spotlightEl = null;
  var cardEl = null;
  var isTourActive = false;

  var accentColor = props.accentColor || '#6366f1';
  var cardTheme = props.cardTheme || 'glass';
  var backdropOpacity = parseFloat(props.backdropOpacity) || 0.75;
  var spotlightPad = parseInt(props.spotlightPadding) || 10;
  var showAvatar = props.showAvatar !== false && props.showAvatar !== 'false';
  var avatarUrl = (props.avatarUrl || '').trim();
  var avatarName = esc(props.avatarName || 'Nova');
  var avatarStyle = props.avatarStyle || 'peeking';
  var tourBadge = esc(props.tourBadge || 'GUIDED TOUR');
  var storageKey = props.tourStorageKey || 'aether_tour_completed';

  root.style.setProperty('--tour-accent', accentColor);

  function createOverlay() {
    if (document.getElementById('wb-tour-overlay')) {
      document.getElementById('wb-tour-overlay').remove();
    }

    overlayEl = document.createElement('div');
    overlayEl.id = 'wb-tour-overlay';
    overlayEl.style.setProperty('--tour-accent', accentColor);
    overlayEl.style.setProperty('--tour-opacity', backdropOpacity);

    spotlightEl = document.createElement('div');
    spotlightEl.className = 'wb-tour-spotlight-hole';
    overlayEl.appendChild(spotlightEl);

    cardEl = document.createElement('div');
    cardEl.className = 'wb-tour-card wb-tour-theme-' + cardTheme;
    overlayEl.appendChild(cardEl);

    document.body.appendChild(overlayEl);

    // Keyboard handlers
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('resize', onViewportChange);
    window.addEventListener('scroll', onViewportChange, true);
  }

  function removeOverlay() {
    isTourActive = false;
    window.removeEventListener('keydown', onKeyDown);
    window.removeEventListener('resize', onViewportChange);
    window.removeEventListener('scroll', onViewportChange, true);

    if (overlayEl) {
      overlayEl.remove();
      overlayEl = null;
      spotlightEl = null;
      cardEl = null;
    }
  }

  function onKeyDown(e) {
    if (!isTourActive) return;
    if (e.key === 'Escape') {
      endTour(false);
    } else if (e.key === 'ArrowRight' || e.key === 'Enter') {
      nextStep();
    } else if (e.key === 'ArrowLeft') {
      prevStep();
    }
  }

  var scrollTimer = null;
  function onViewportChange() {
    if (!isTourActive) return;
    clearTimeout(scrollTimer);
    scrollTimer = setTimeout(function () {
      updatePositions(currentStep);
    }, 40);
  }

  function findTargetElement(selector) {
    if (!selector) return null;
    var selectors = selector.split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    for (var i = 0; i < selectors.length; i++) {
      var found = document.querySelector(selectors[i]);
      if (found && found.offsetParent !== null) return found;
    }
    return null;
  }

  function updatePositions(stepIdx) {
    if (!isTourActive || !cardEl || !spotlightEl) return;
    var step = steps[stepIdx];
    if (!step) return;

    var target = findTargetElement(step.targetSelector);
    var rect;

    if (target) {
      rect = target.getBoundingClientRect();
      var top = Math.max(4, rect.top - spotlightPad);
      var left = Math.max(4, rect.left - spotlightPad);
      var width = rect.width + (spotlightPad * 2);
      var height = rect.height + (spotlightPad * 2);

      spotlightEl.style.top = top + 'px';
      spotlightEl.style.left = left + 'px';
      spotlightEl.style.width = width + 'px';
      spotlightEl.style.height = height + 'px';
      spotlightEl.style.display = 'block';
    } else {
      // Fallback: spotlight center box if element not on page
      var w = 180, h = 90;
      var cx = (window.innerWidth / 2) - (w / 2);
      var cy = (window.innerHeight / 2) - (h / 2);
      spotlightEl.style.top = cy + 'px';
      spotlightEl.style.left = cx + 'px';
      spotlightEl.style.width = w + 'px';
      spotlightEl.style.height = h + 'px';
      spotlightEl.style.display = 'none';
      rect = { top: cy, bottom: cy + h, left: cx, right: cx + w, width: w, height: h };
    }

    // Card Position calculation
    var placement = step.placement || 'auto';
    var cardW = cardEl.offsetWidth || 360;
    var cardH = cardEl.offsetHeight || 220;
    var cTop, cLeft;

    if (placement === 'auto') {
      var spaceBelow = window.innerHeight - rect.bottom;
      var spaceAbove = rect.top;
      placement = (spaceBelow >= cardH + 24) ? 'bottom' : (spaceAbove >= cardH + 24 ? 'top' : 'bottom');
    }

    if (placement === 'bottom') {
      cTop = rect.bottom + 16;
      cLeft = rect.left + (rect.width / 2) - (cardW / 2);
    } else if (placement === 'top') {
      cTop = rect.top - cardH - 16;
      cLeft = rect.left + (rect.width / 2) - (cardW / 2);
    } else if (placement === 'right' && rect.right + cardW + 20 < window.innerWidth) {
      cTop = rect.top + (rect.height / 2) - (cardH / 2);
      cLeft = rect.right + 16;
    } else if (placement === 'left' && rect.left - cardW - 20 > 0) {
      cTop = rect.top + (rect.height / 2) - (cardH / 2);
      cLeft = rect.left - cardW - 16;
    } else {
      // Fallback center
      cTop = (window.innerHeight / 2) - (cardH / 2);
      cLeft = (window.innerWidth / 2) - (cardW / 2);
    }

    // Viewport Boundary Clamping
    cLeft = Math.max(16, Math.min(window.innerWidth - cardW - 16, cLeft));
    cTop = Math.max(48, Math.min(window.innerHeight - cardH - 16, cTop));

    cardEl.style.top = Math.round(cTop) + 'px';
    cardEl.style.left = Math.round(cLeft) + 'px';
  }

  function renderCardContent(step, idx) {
    var isLast = idx === steps.length - 1;
    var isFirst = idx === 0;

    // Avatar HTML
    var peekingHtml = '';
    var badgeAvatarHtml = '';
    if (showAvatar && avatarUrl) {
      if (avatarStyle === 'peeking') {
        peekingHtml = '<div class="wb-tour-avatar-peeking"><img src="' + esc(avatarUrl) + '" alt="' + avatarName + '" /></div>';
      } else if (avatarStyle === 'badge') {
        badgeAvatarHtml = '<span class="wb-tour-avatar-badge"><img src="' + esc(avatarUrl) + '" alt="' + avatarName + '" /></span>';
      } else if (avatarStyle === 'companion') {
        peekingHtml = '<div class="wb-tour-avatar-companion"><img src="' + esc(avatarUrl) + '" alt="' + avatarName + '" /></div>';
      }
    }

    // Dots HTML
    var dotsHtml = '<div class="wb-tour-progress-bar">';
    for (var i = 0; i < steps.length; i++) {
      dotsHtml += '<span class="wb-tour-dot ' + (i === idx ? 'active' : '') + '"></span>';
    }
    dotsHtml += '</div>';

    var iconHtml = step.stepIcon ? '<span style="font-size:1.15rem;margin-right:6px;">' + esc(step.stepIcon) + '</span>' : '';

    cardEl.innerHTML =
      peekingHtml +
      '<div class="wb-tour-card-header">' +
        '<span class="wb-tour-badge-pill">' + badgeAvatarHtml + tourBadge + '</span>' +
        '<span class="wb-tour-step-counter">Step ' + (idx + 1) + ' of ' + steps.length + '</span>' +
        '<button type="button" class="wb-tour-close-btn" title="Exit Tour">✕</button>' +
      '</div>' +
      '<h4 class="wb-tour-card-title">' + iconHtml + esc(step.title || 'Step ' + (idx + 1)) + '</h4>' +
      '<p class="wb-tour-card-desc">' + esc(step.content || '') + '</p>' +
      dotsHtml +
      '<div class="wb-tour-card-actions">' +
        '<button type="button" class="wb-tour-skip-btn">Skip Tour</button>' +
        '<div class="wb-tour-nav-btns">' +
          '<button type="button" class="wb-tour-btn wb-tour-btn-back" ' + (isFirst ? 'disabled' : '') + '>Back</button>' +
          '<button type="button" class="wb-tour-btn wb-tour-btn-next">' + (isLast ? 'Finish 🎉' : 'Next →') + '</button>' +
        '</div>' +
      '</div>';

    // Wire Card Buttons
    cardEl.querySelector('.wb-tour-close-btn').onclick = function () { endTour(false); };
    cardEl.querySelector('.wb-tour-skip-btn').onclick = function () { endTour(false); };
    cardEl.querySelector('.wb-tour-btn-back').onclick = function () { prevStep(); };
    cardEl.querySelector('.wb-tour-btn-next').onclick = function () {
      if (isLast) {
        endTour(true);
      } else {
        nextStep();
      }
    };
  }

  function goToStep(idx) {
    if (idx < 0 || idx >= steps.length) return;
    currentStep = idx;

    var step = steps[idx];
    var target = findTargetElement(step.targetSelector);

    if (target) {
      try {
        target.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
      } catch (_) {}
    }

    renderCardContent(step, idx);

    setTimeout(function () {
      updatePositions(idx);
    }, 150);
  }

  function nextStep() {
    if (currentStep < steps.length - 1) {
      goToStep(currentStep + 1);
    } else {
      endTour(true);
    }
  }

  function prevStep() {
    if (currentStep > 0) {
      goToStep(currentStep - 1);
    }
  }

  function startTour() {
    if (steps.length === 0) return;
    isTourActive = true;
    createOverlay();
    goToStep(0);
  }

  function endTour(completed) {
    removeOverlay();
    if (completed && storageKey) {
      try {
        localStorage.setItem(storageKey, 'true');
      } catch (_) {}
    }
    if (completed && window.aetherApp && window.aetherApp.canvas && typeof window.aetherApp.canvas.showToast === 'function') {
      window.aetherApp.canvas.showToast('🎉 Tour completed! Welcome aboard.', 'success');
    }
  }

  // Wire Launcher Button
  var launcherBtn = root.querySelector('.wb-tour-launcher-btn');
  if (launcherBtn) {
    launcherBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      startTour();
    });
  }

  // Auto-Start Check
  if (props.autoStart === true || props.autoStart === 'true') {
    var alreadyDone = false;
    try {
      alreadyDone = !!localStorage.getItem(storageKey);
    } catch (_) {}

    if (!alreadyDone) {
      setTimeout(function () {
        // Only auto-start if not already in another tour
        if (!isTourActive) startTour();
      }, 1000);
    }
  }

  // Teardown
  el.__wbDestroy = function () {
    removeOverlay();
  };
}
